    completed_run_id VARCHAR,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    PRIMARY KEY (user_id, id),
    CONSTRAINT fk_studytask_completed_run_id FOREIGN KEY(user_id, completed_run_id) REFERENCES academy_stage.lessonrun (user_id, id),
